/**
 * ui/src/create-donors-client-container.ts — 客户端控件容器 donor（模板 + 布局实例）
 *
 * 来源 = 2026-10-28 真机 GIA 导入 + 用户把模板拖入布局后的差分：
 *   `workspace/flower-tea/device-package/1073741840.after-layout-20261028-1037.gil`
 *
 * 旧 donor（2026-10-23 hl 的 1891/1892）只有布局组+节点，没有模板来源；
 * 编辑器保存时会把它当普通容器重排/剪掉，脚本挂载丢失（2002/2003 还被特殊根占用）。
 *
 * 正确形态（编辑器导入 GIA + 拖入布局实测）：
 *   - 模板组 2007（无 f504，模板区） + 模板节点 2008
 *   - 布局实例组 2014（f504=默认布局 1825，内部 f502 引用模板组 2007） + 布局节点 2015
 * 布局实例组与模板组之间通过 f502 引用；节点没有 f504 父字段，由组内 f502 引用。
 *
 * 装配 = 克隆模板组/节点、布局组/节点，remap 自身的 2007/2008/2014/2015/1825；
 * 模板组/节点只插记录；布局组追加到布局 f503；布局节点只插记录。
 */

export interface ClientContainerGroupDonor {
  id: string
  sourceSnapshot: string
  /** 记录自身 ID（顶层 f501） */
  selfId: number
  /** 父引用（模板组没有 f504，填 0；布局组为默认布局 1825） */
  parentId: number
  /** f502 引用的子控件 ID */
  childId: number
  /** 布局实例组额外引用的模板组 ID（模板组本身没有） */
  templateGroupId?: number
  sha256: string
  hex: string
}

export interface ClientContainerChildDonor {
  selfId: number
  sha256: string
  hex: string
}

